const BUILD = "CDF-V12.4-WORKER-BUNDLE";
const THREE_VERSION = "0.181.2";
const GAME_HTML_B64 = "";

function gameHtml() {
  const bytes = Uint8Array.from(atob(GAME_HTML_B64), c => c.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}

function text(body, status=200, extra={}) {
  return new Response(body, {status, headers: {"content-type":"text/plain; charset=utf-8", ...extra}});
}

async function proxyThree(request, url) {
  const prefix = "/vendor/three/";
  const rel = url.pathname.slice(prefix.length);
  if (!rel || rel.includes("..") || !/^[A-Za-z0-9_./-]+$/.test(rel)) return text("Invalid vendor path", 400);
  const upstreamUrl = `https://cdn.jsdelivr.net/npm/three@${THREE_VERSION}/${rel}`;
  try {
    const upstream = await fetch(upstreamUrl, {
      method: request.method === "HEAD" ? "HEAD" : "GET",
      headers: {"accept": "*/*"},
      cf: {cacheEverything: true, cacheTtl: 604800}
    });
    if (!upstream.ok) return text(`Three upstream ${upstream.status}: ${rel}`, 502, {"x-cdf-build": BUILD});
    const h = new Headers(upstream.headers);
    h.set("cache-control", "public, max-age=604800, immutable");
    h.set("access-control-allow-origin", "*");
    h.set("x-cdf-build", BUILD);
    h.set("x-cdf-three-version", THREE_VERSION);
    if (rel.endsWith(".js")) h.set("content-type", "text/javascript; charset=utf-8");
    return new Response(request.method === "HEAD" ? null : upstream.body, {status: 200, headers: h});
  } catch (e) {
    return text(`Proxy fetch failed: ${e?.message || e}`, 502, {"x-cdf-build": BUILD});
  }
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === "/__cdf_status" || url.pathname === "/build-id.txt") {
      let vendor = {ok:false,status:0};
      try {
        const r = await fetch(`https://cdn.jsdelivr.net/npm/three@${THREE_VERSION}/build/three.module.js`, {cf: {cacheEverything:true, cacheTtl:300}});
        vendor = {ok:r.ok,status:r.status};
      } catch(e) { vendor = {ok:false,status:0,error:String(e?.message||e)}; }
      if (url.pathname === "/build-id.txt") return text(BUILD+"\n",200,{"cache-control":"no-store","x-cdf-build":BUILD});
      return new Response(JSON.stringify({build:BUILD,threeVersion:THREE_VERSION,worker:true,vendorUpstream:vendor,time:new Date().toISOString()},null,2), {headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-cdf-build":BUILD}});
    }
    if (url.pathname.startsWith("/vendor/three/")) return proxyThree(request, url);
    // Serve the game directly from the Worker. No Pages/static asset can override it.
    if (request.method !== "GET" && request.method !== "HEAD") return text("Method not allowed",405);
    const h = new Headers({
      "content-type":"text/html; charset=utf-8",
      "cache-control":"no-store, no-cache, must-revalidate, max-age=0",
      "pragma":"no-cache",
      "expires":"0",
      "x-cdf-build":BUILD
    });
    return new Response(request.method === "HEAD" ? null : gameHtml(), {status:200,headers:h});
  }
};
